import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        long maxVal = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            long v = sc.nextLong();
            if (v > maxVal) maxVal = v;
        }
        System.out.println(maxVal);
    }
}

