#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long max_val, val;
    scanf("%lld", &max_val);
    for (int i = 1; i < n; i++) {
        scanf("%lld", &val);
        if (val > max_val) max_val = val;
    }
    printf("%lld\n", max_val);
    return 0;
}
